ctionSubLineItems].[Tax2],[dbo].[tblTransactionSubLineItems].[Tax3],[dbo].[tblTransactionSubLineItems].[Tax4],[dbo].[tblTransactionSubLineItems].[Tax5],[dbo].[tblTransactionSubLineItems].[TransVersion],[dbo].[tblTransactionSubLineItems].[ImproperAdditization],[dbo].[tblTransactionSubLineItems].[BrokenBlend],[dbo].[tblTransactionSubLineItems].[Flag01],[dbo].[tblTransactionSubLineItems].[Flag02],[dbo].[tblTransactionSubLineItems].[Flag03],[dbo].[tblTransactionSubLineItems].[Flag04],[dbo].[tblTransactionSubLineItems].[Flag05],[dbo].[tblTransactionSubLineItems].[Flag06],[dbo].[tblTransactionSubLineItems].[Number01],[dbo].[tblTransactionSubLineItems].[Number02],[dbo].[tblTransactionSubLineItems].[Number03],[dbo].[tblTransactionSubLineItems].[Number04],[dbo].[tblTransactionSubLineItems].[Number05],[dbo].[tblTransactionSubLineItems].[Number06],[dbo].[tblTransactionSubLineItems].[Date01],[dbo].[tblTransactionSubLineItems].[Date02],[dbo].[tblTransactionSubLineItems].[Date03],[dbo].[tblTransactionSubLineItems].[Date04],[dbo].[tblTransactionSubLineItems].[MassQuantity],[dbo].[tblTransactionSubLineItems].[NetManualValueFlag],[dbo].[tblTransactionSubLineItems].[MassManualValueFlag],[dbo].[tblTransactionSubLineItems].[GrossManualValueFlag],[dbo].[tblTransactionSubLineItems].[VcfManualValueFlag],[dbo].[tblTransactionSubLineItems].[DeliveredGrossManualValueFlag],[dbo].[tblTransactionSubLineItems].[DeliveredNetManualValueFlag],[dbo].[tblTransactionSubLineItems].[TransactionSubLineItemGuid],[dbo].[tblTransactionSubLineItems].[LookupTransactionStatusIndex],[dbo].[tblTransactionSubLineItems].[LookupQualityIndex],[dbo].[tblTransactionSubLineItems].[TransactionLineItemGuid],[dbo].[tblTransactionSubLineItems].[ProductGuid],[dbo].[tblTransactionSubLineItems].[TransactionGuid],[dbo].[tblTransactionSubLineItems].[StorageLocationTankGuid],[dbo].[tblTransactionSubLineItems].[MeterGuid],[dbo].[tblTransactionSubLineItems].[PackageManualValueFlag],[dbo].[tblTransactionSubLineItems].[CleanLineItem